def semver_sort(versions):
    def parse_version(version):
        # Split off build metadata (everything after '+')
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version

        # Split off pre-release (everything after '-')
        if '-' in version_part:
            core, prerelease = version_part.split('-', 1)
        else:
            core = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            prerelease_identifiers = prerelease.split('.')
            # Convert to tuples for comparison
            parsed_identifiers = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    parsed_identifiers.append((0, int(identifier)))
                else:
                    parsed_identifiers.append((1, identifier))
            prerelease_tuple = tuple(parsed_identifiers)
        else:
            # No pre-release means it sorts after any pre-release of same version
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_tuple = parse_version(version)

        # For sorting: versions without pre-release should come after those with pre-release
        # So we use (major, minor, patch, has_prerelease, prerelease_identifiers, index)
        # where has_prerelease is False (sorts before) if there's a pre-release, True if not
        if prerelease_tuple is None:
            return (major, minor, patch, 1, (), index)
        else:
            return (major, minor, patch, 0, prerelease_tuple, index)

    # Add index to maintain stable sort for equal precedence
    indexed_versions = [(i, v) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=sort_key)

    return [v for _, v in sorted_versions]

